-- Additive DEV-only purchase-invoice authority. Run after 20260929160000 only.
CREATE TYPE "FacturaCompraState" AS ENUM ('Pendiente', 'Pagada', 'Anulada');
CREATE TABLE "FacturaCompra" ("id" TEXT NOT NULL, "companyId" TEXT NOT NULL, "proveedorId" TEXT NOT NULL, "proveedorName" TEXT NOT NULL, "number" TEXT NOT NULL, "date" TIMESTAMP(3) NOT NULL, "total" DECIMAL(14,4) NOT NULL DEFAULT 0, "state" "FacturaCompraState" NOT NULL DEFAULT 'Pendiente', "ordenCompraId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "pagadaAt" TIMESTAMP(3), "anuladaAt" TIMESTAMP(3), "observaciones" TEXT, CONSTRAINT "FacturaCompra_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FacturaCompraItem" ("id" TEXT NOT NULL, "facturaCompraId" TEXT NOT NULL, "stockItemId" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NOT NULL, "quantity" DECIMAL(14,4) NOT NULL, "unitPrice" DECIMAL(14,4) NOT NULL, "subtotal" DECIMAL(14,4) NOT NULL, "descripcionLibre" TEXT, CONSTRAINT "FacturaCompraItem_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "uq_factura_compra_company_id" ON "FacturaCompra"("companyId", "id"); CREATE INDEX "ix_factura_compra_company_state" ON "FacturaCompra"("companyId", "state"); CREATE INDEX "ix_factura_compra_company_date" ON "FacturaCompra"("companyId", "date" DESC); CREATE INDEX "ix_factura_compra_company_proveedor" ON "FacturaCompra"("companyId", "proveedorId"); CREATE INDEX "ix_factura_compra_company_orden_compra" ON "FacturaCompra"("companyId", "ordenCompraId"); CREATE INDEX "ix_factura_compra_item_fc" ON "FacturaCompraItem"("facturaCompraId");
ALTER TABLE "FacturaCompra" ADD CONSTRAINT "FacturaCompra_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "FacturaCompraItem" ADD CONSTRAINT "FacturaCompraItem_facturaCompraId_fkey" FOREIGN KEY ("facturaCompraId") REFERENCES "FacturaCompra"("id") ON DELETE CASCADE ON UPDATE CASCADE;
